// Run from currency_dart: dart run tool/generate.dart [--check]
import 'dart:convert';
import 'dart:io';

void main(List<String> arguments) {
  final root = File.fromUri(Platform.script).parent.parent.parent;
  final source = File('${root.path}/data/currencies/currency.json');
  final decoded = jsonDecode(source.readAsStringSync()) as Map<String, dynamic>;
  final keys = decoded.keys.toList()..sort();
  final output = StringBuffer(
    '// GENERATED by currency_dart/tool/generate.dart. Do not edit.\n'
    '// Source: data/currencies/currency.json; provenance: data/currencies/currency.metadata.json.\n'
    'class CurrencyRepo {\n'
    '  static const Map<String, Map<String, dynamic>> currencies = {\n',
  );
  String literal(Object? value) {
    if (value is String) return jsonEncode(value).replaceAll(r'$', r'\$');
    if (value is List) {
      return value.isEmpty ? '[]' : '[${value.map(literal).join(', ')},]';
    }
    return jsonEncode(value);
  }

  for (final code in keys) {
    final fields = decoded[code] as Map<String, dynamic>;
    if (fields['code'] != code) throw StateError('Mismatched code: $code');
    output.writeln('    ${literal(code)}: {');
    for (final entry in fields.entries) {
      output.writeln('      ${literal(entry.key)}: ${literal(entry.value)},');
    }
    output.writeln('    },');
  }
  output.write('  };\n}\n');
  final target = File('${root.path}/currency_dart/lib/src/currency_repo.dart');
  // Format generated output with the same SDK used by the caller.
  final temporary = File('${target.path}.tmp.dart');
  try {
    temporary.writeAsStringSync(output.toString());
    final formatted = Process.runSync(Platform.resolvedExecutable, [
      '--suppress-analytics',
      'format',
      temporary.path,
    ]);
    if (formatted.exitCode != 0) {
      throw StateError('Formatting generated data failed: ${formatted.stderr}');
    }
    final content = temporary.readAsStringSync();
    if (arguments.contains('--check')) {
      if (!target.existsSync() || target.readAsStringSync() != content) {
        stderr.writeln(
            'Generated data is stale; run dart run tool/generate.dart');
        exitCode = 1;
      }
    } else {
      target.writeAsStringSync(content);
    }
  } finally {
    if (temporary.existsSync()) temporary.deleteSync();
  }
}
